\set ON_ERROR_STOP on
BEGIN;
INSERT INTO organizations(id,org_name,status,apify_status,apify_api_key,monthly_credit_limit,credits_used) VALUES
 (920001,'Billing fixture A','active','active','apify_api_TESTBYOK',20,0),
 (920002,'Billing fixture B','active','active','apify_api_TESTB',20,0);
UPDATE gathering_accounts SET api_key='apify_api_TESTPLATFORM',enabled=true,monthly_budget_usd=5,max_concurrent=1,price_multiplier=1 WHERE mode='platform';
INSERT INTO gathering_accounts(mode,org_id,api_key,enabled,monthly_budget_usd,max_concurrent) VALUES('byok',920001,'apify_api_TESTBYOK',true,20,1);
DO $$
DECLARE p jsonb;a jsonb;b jsonb;j integer;j2 integer;j3 integer;account bigint;old_balance numeric;rows jsonb;report jsonb;n integer;
BEGIN
 p:='{"org_id":920001,"billing_mode":"platform","result_mode":"new","source":"google_maps","job_name":"Billing test","search_query":"Dentists","location":"Test City","max_results":2,"candidate_limit":6,"max_cost_usd":0.5,"request_id":"billing_request_01","refresh":true}';
 a:=gathering_enqueue_v3(p);ASSERT a->>'code'='INSUFFICIENT_PLATFORM_CREDITS','monthly allowance treated as prepaid money';
 PERFORM gathering_wallet_credit(920001,5,'test_payment_01');PERFORM gathering_wallet_credit(920001,5,'test_payment_01');
 ASSERT (SELECT sum(amount_usd) FROM gathering_wallet_entries WHERE org_id=920001)=5,'payment credited twice';
 PERFORM gathering_wallet_credit(920002,5,'test_payment_02');
 a:=gathering_enqueue_v3(p);j:=(a->>'job_id')::integer;ASSERT a->>'status'='queued' AND a->>'dispatch'='false','job bypassed queue';
 a:=gathering_claim_v3(j,920001,'google_maps','premature');ASSERT a->>'claimed'='false','queued job started without capacity lease';
 a:=gathering_enqueue_v3(p);ASSERT a->>'replayed'='true' AND a->>'job_id'=j::text;
 a:=gathering_enqueue_v3(p||'{"billing_mode":"byok"}');ASSERT a->>'code'='REQUEST_ID_CONFLICT','billing mode changed on replay';
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_request_02","org_id":920002}');j2:=(a->>'job_id')::integer;
 SELECT count(*) INTO n FROM gathering_dispatch_v3();ASSERT n=1,'account concurrency exceeded';
 a:=gathering_claim_v3(j,920001,'google_maps','worker1');ASSERT a->>'claimed'='true' AND a->>'apify_api_key'='apify_api_TESTPLATFORM','wrong billing account';
 a:=gathering_claim_v3(j,920001,'google_maps','worker2');ASSERT a->>'claimed'='false';
 UPDATE scraping_jobs SET apify_actor_run_id='billing-run-1',dataset_id='billing-data-1' WHERE id=j;
 INSERT INTO staging_leads(org_id,company_name,source,source_record_id,processing_status,processed) VALUES(920001,'Previously known clinic','google_maps','known','pending',false);
 rows:='[{"ordinal":0,"company_name":"Known","source_record_id":"known"},{"ordinal":1,"company_name":"Known again","source_record_id":"known"},{"ordinal":2,"company_name":"New A","source_record_id":"new-a"},{"ordinal":3,"company_name":"New B","source_record_id":"new-b"},{"ordinal":4,"company_name":"Surplus C","source_record_id":"new-c"}]';
 a:=gathering_finish_v3(j,920001,rows,0.04,5,'[]','SUCCEEDED','worker1');ASSERT a->>'new_leads'='2' AND a->>'shortfall'='0','existing rows consumed new target';
 report:=gathering_report_v3(j,920001);ASSERT report->>'existing_matches'='1' AND report->>'duplicate_records'='2','existing matches not unique';
 ASSERT report->>'customer_charge_usd'='0.040000','wrong wallet charge';
 ASSERT (SELECT count(*) FROM staging_leads WHERE org_id=920001)=3,'surplus leads inserted beyond target';
 a:=gathering_finish_v3(j,920001,rows,9,5,'[]','SUCCEEDED','worker1');ASSERT a->>'replayed'='true';
 ASSERT (SELECT sum(amount_usd) FROM gathering_wallet_entries WHERE org_id=920001)=4.96,'job charged twice';
 SELECT count(*) INTO n FROM gathering_dispatch_v3();ASSERT n=1;
 a:=gathering_claim_v3(j2,920002,'google_maps','worker-b');ASSERT a->>'claimed'='true','second organization starved';
 UPDATE scraping_jobs SET apify_actor_run_id='billing-run-b',dataset_id='billing-data-b' WHERE id=j2;
 PERFORM gathering_finish_v3(j2,920002,'[]',0.01,0,'[]','SUCCEEDED','worker-b');
 report:=gathering_report_v3(j2,920002);ASSERT report->>'shortfall'='2' AND report->>'completion_reason'='source_or_provider_limit';
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_byok_01","billing_mode":"byok"}');j3:=(a->>'job_id')::integer;
 PERFORM gathering_dispatch_v3();a:=gathering_claim_v3(j3,920001,'google_maps','byok-worker');ASSERT a->>'apify_api_key'='apify_api_TESTBYOK','BYOK silently used platform';
 UPDATE scraping_jobs SET apify_actor_run_id='byok-run',dataset_id='byok-data' WHERE id=j3;
 PERFORM gathering_finish_v3(j3,920001,rows,0.03,5,'[]','SUCCEEDED','byok-worker');
 ASSERT (SELECT sum(amount_usd) FROM gathering_wallet_entries WHERE org_id=920001)=4.96,'BYOK debited platform wallet';
 ASSERT (SELECT credits_used FROM organizations WHERE id=920001)=0,'BYOK debited old allowance';
 ASSERT (SELECT customer_charge_usd FROM scraping_jobs WHERE id=j3)=0;
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_cancel_01"}');j3:=(a->>'job_id')::integer;
 a:=gathering_control_v3(j3,920002,'cancel');ASSERT a->>'http_status'='404','cross-tenant cancel';
 a:=gathering_control_v3(j3,920001,'cancel');ASSERT a->>'status'='cancelled';
 ASSERT (SELECT customer_charge_usd FROM scraping_jobs WHERE id=j3)=0;
 UPDATE gathering_accounts SET enabled=false WHERE mode='platform';
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_disabled_01"}');ASSERT a->>'code'='PLATFORM_NOT_CONFIGURED','silent fallback to BYOK';
 UPDATE gathering_accounts SET enabled=true,price_multiplier=2 WHERE mode='platform';
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_price_01"}');ASSERT a->>'code'='PRICE_CONFIRMATION_REQUIRED';
 UPDATE gathering_accounts SET price_multiplier=1,monthly_budget_usd=0.1 WHERE mode='platform';
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_budget_01"}');ASSERT a->>'code'='PROVIDER_BUDGET_EXHAUSTED';
 UPDATE gathering_accounts SET monthly_budget_usd=5 WHERE mode='platform';
 a:=gathering_enqueue_v3(p||'{"request_id":"billing_unknown_cost"}');j3:=(a->>'job_id')::integer;
 PERFORM gathering_dispatch_v3();PERFORM gathering_claim_v3(j3,920001,'google_maps','unknown-cost');
 UPDATE scraping_jobs SET apify_actor_run_id='unknown-run',dataset_id='unknown-data' WHERE id=j3;
 PERFORM gathering_finish_v3(j3,920001,'[]',NULL,0,'[]','SUCCEEDED','unknown-cost');
 report:=gathering_report_v3(j3,920001);ASSERT report->>'billing_needs_attention'='true';
 a:=gathering_quote_v3(920001,'platform',0.5);ASSERT (a->>'wallet_available_usd')::numeric=4.46,'unknown cost released reservation';
 PERFORM gathering_reconcile_cost_v3(j3,920001,0.6);PERFORM gathering_reconcile_cost_v3(j3,920001,0.6);
 ASSERT (SELECT sum(amount_usd) FROM gathering_wallet_entries WHERE org_id=920001)=4.46,'provider overshoot exceeded customer approval';
 ASSERT (SELECT amount_usd FROM gathering_costs WHERE job_id=j3)=0.6,'provider overshoot hidden';
 report:=gathering_report_v3(j3,920001);ASSERT report->>'billing_needs_attention'='false' AND report->>'provider_budget_exceeded'='true';
 ASSERT gathering_report_v3(j,920002) IS NULL;
 RAISE NOTICE 'PASS: wallets, immutable billing, queue capacity, provider routing, new-only targets, shortfalls, exact-once charges, BYOK isolation, cancellation, limits and tenant separation';
END $$;
ROLLBACK;
